            title="Cambia visualizzazione tra note in caduta (Cascata) e pentagramma scorrevole (Spartito)"
          >
            <span>{viewMode === 'sheet' ? '🎼 Spartito' : '🎹 Cascata'}</span>
          </button>

          {/* Quick Info: Standard Fingering Rules button */}
          <button
