                  >
                    <span>👁️ Simulate Student View</span>
                  </button>

                  {/* VIVAVOCE VOCALE AUDIO CONTROLS (MAESTRO) */}
                  <div className="flex items-center gap-1 bg-slate-950/90 border border-slate-800 rounded-lg p-0.5 shrink-0">
                    {!isVoiceActive ? (
                      <button
                        onClick={startVoiceCall}
