                        <button
                          onClick={stopVoiceCall}
                          className="px-1.5 py-0.5 bg-slate-800 hover:bg-red-900/60 text-slate-300 hover:text-red-300 rounded text-[10px] cursor-pointer"
                          title="Disable speakerphone"
                        >
                          ✕
                        </button>
                      </div>
